function BadgePill({ badge }: { badge: string }) {
  const isPawpy = badge.toLowerCase().startsWith('pawpy')
  return (
    <div className="flex items-center gap-1 bg-[#fcfaf7] px-1 py-1 rounded-full">
      {isPawpy ? <PawIcon /> : <CheckCircleIcon />}
      <span className="text-[11px] text-[#010a05] leading-[1.1] whitespace-nowrap pr-0.5">{badge}</span>
    </div>
  )
}

function SitterCard({
  sitter,
  onToggleFavorite,
  onClick,
}: {
  sitter: SitterProfile
  onToggleFavorite: () => void
  onClick: () => void
}) {
  const gradient = getGradient(sitter.id)

  return (
    <div
      className="relative flex-1 h-[271px] rounded-lg overflow-hidden cursor-pointer"
      onClick={onClick}
    >
      {/* Background photo placeholder */}
      <div className={`absolute inset-0 bg-gradient-to-br ${gradient}`} />
      {/* Initials overlay */}
      <div className="absolute inset-0 flex items-center justify-center">
        <span className="text-white/30 text-5xl font-bold select-none">
          {sitter.firstName[0]}{sitter.lastName[0]}
        </span>
      </div>
      {/* Bottom gradient */}
      <div
        className="absolute inset-0"
        style={{ background: 'linear-gradient(180deg, rgba(0,0,0,0) 57%, rgba(0,0,0,0.7) 87%)' }}
      />

      {/* Top row: badges + heart */}
      <div className="absolute top-2 left-2 right-2 flex items-start justify-between">
        <div className="flex flex-col gap-2">
          {sitter.badges.map(badge => (
            <BadgePill key={badge} badge={badge} />
          ))}
        </div>
        <button
          className={`${glassStyle} flex items-center justify-center rounded-full size-8 flex-shrink-0`}
          onClick={e => { e.stopPropagation(); onToggleFavorite() }}
        >
          <HeartFilledIcon />
        </button>
      </div>

      {/* Bottom: rating + name */}
      <div className="absolute bottom-2 left-2 right-2 flex flex-col gap-1">
        <div className="flex items-center gap-1">
          <span className="text-white text-[14px] leading-[1.2] tracking-[-0.14px]">
            {sitter.rating.toFixed(1)}
          </span>
          <StarHalfIcon />
        </div>
        <p className="text-[#f0efeb] text-[16px] leading-[1.2] tracking-[-0.16px] truncate">
          {sitter.firstName} {sitter.lastName}
        </p>
      </div>
    </div>
  )
}

export default function OwnerFavoris() {
  const navigate = useNavigate()
  const { favoriteSitterIds, toggleFavoriteSitter } = useFavorites()
  const { sitterProfiles } = useSitterProfiles()

  const favorites = sitterProfiles.filter(s => favoriteSitterIds.includes(s.id))

  // Pair up into rows of 2
  const rows: SitterProfile[][] = []
  for (let i = 0; i < favorites.length; i += 2) {
    rows.push(favorites.slice(i, i + 2))
  }

  return (
    <div className="flex flex-col h-full bg-[#fcfaf7] pt-[62px] pb-[127px] px-4 gap-8 overflow-y-auto">
      {/* Header */}
      <div className="flex items-center gap-2 flex-shrink-0">
        <button
          onClick={() => navigate(-1)}
          className={`${glassStyle} flex items-center justify-center p-3 rounded-full flex-shrink-0`}
        >
          <BackIcon />
        </button>
        <h1
          className="flex-1 text-[22px] font-semibold text-[#010a05] leading-[1.2] tracking-[-0.44px]"
          style={{ fontFeatureSettings: "'case' 1" }}
        >
          Favoris
        </h1>
      </div>

      {/* Content */}
      {favorites.length === 0 ? (
        <div className="flex flex-col items-center justify-center flex-1 gap-3 text-center">
          <p className="text-[22px] font-semibold text-[#010a05] leading-[1.2] tracking-[-0.44px]">
            Aucun favori
          </p>
          <p className="text-base text-[#7e8280] leading-[1.2] tracking-[-0.16px]">
            Ajoutez des promeneurs à vos favoris depuis la page recherche.
          </p>
        </div>
      ) : (
        <div className="flex flex-col gap-4">
          {rows.map((row, i) => (
            <div key={i} className="flex gap-4 h-[271px]">
              {row.map(sitter => (
                <SitterCard
                  key={sitter.id}
                  sitter={sitter}
                  onToggleFavorite={() => toggleFavoriteSitter(sitter.id)}
                  onClick={() => navigate(`/owner/recherche/${sitter.id}`)}
                />
              ))}
              {/* Fill empty slot in last row with odd count */}
              {row.length === 1 && <div className="flex-1" />}
            </div>
          ))}
        </div>
      )}
    </div>
  )
}
